  static void SonarGuidance(SubmarineMatch m){var guidance=m.gameObject.AddComponent<SubmarineSonarGuidance>();guidance.match=m;guidance.compasses=new SportsBroadcastCompass[5];guidance.markers=new CompassProPOI[5];var prefab=Require<GameObject>("Assets/TruckSports/Resources/Broadcast objective compass.prefab");for(int i=0;i<5;i++){var root=(GameObject)PrefabUtility.InstantiatePrefab(prefab,m.transform);root.name="Original CNP discovered-only submarine objective "+i;root.SetActive(false);var compass=root.GetComponent<SportsBroadcastCompass>();if(compass==null)throw new InvalidOperationException("Existing CNP production adapter required.");int group=i==4?1:i+1;var settings=new SerializedObject(compass);var groupSetting=settings.FindProperty("_compassGroup");if(groupSetting==null)throw new InvalidOperationException("Installed CNP serialized group contract required.");groupSetting.intValue=group;foreach(string field in new[]{"_showCompassBar","_showMiniMap","_dontDestroyOnLoad"}){var property=settings.FindProperty(field);if(property==null)throw new InvalidOperationException("Installed CNP authoring contract missing: "+field);property.boolValue=false;}foreach(string field in new[]{"_showOnScreenIndicators","_showOffScreenIndicators"}){var property=settings.FindProperty(field);if(property==null)throw new InvalidOperationException("Installed CNP authoring contract missing: "+field);property.boolValue=true;}settings.ApplyModifiedPropertiesWithoutUndo();var canvas=compass.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=i==4?m.broadcast.view:m.drivingViews.rally.views[i].view;canvas.planeDistance=.5f;var obj=new GameObject("Exact discovered treasure or carried delivery POI "+i);obj.transform.SetParent(m.transform,false);obj.SetActive(false);var poi=obj.AddComponent<CompassProPOI>();poi.canBeVisited=false;poi.hideWhenVisited=false;poi.dontDestroyOnLoad=false;poi.showOnScreenIndicator=true;poi.showOffScreenIndicator=true;poi.ignoreAreaOfInterest=true;poi.playAudioClipWhenVisited=false;poi.radius=0;var poiSettings=new SerializedObject(poi);poiSettings.FindProperty("_compassGroupMask").intValue=1<<(group-1);poiSettings.ApplyModifiedPropertiesWithoutUndo();poi.iconNonVisited=AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/Knob.psd");compass.permittedTargets=new[]{poi};guidance.compasses[i]=compass;guidance.markers[i]=poi;EditorUtility.SetDirty(compass);PrefabUtility.RecordPrefabInstancePropertyModifications(compass);}}
  static void Gear(SubmarineDiver d,Material metal,Material brass,Material blue,Material glow){var root=new GameObject("Submarine compatible conversion equipment only").transform;root.SetParent(d.transform,false);d.gear=root;var propellers=new List<Transform>();for(int side=-1;side<=1;side+=2){var tank=SubmarineArt.Model("Welded longitudinal pressure ballast tank",root,SubmarineArt.Tank(),blue,new Vector3(side*2.1f,.3f,-.7f));tank.transform.localRotation=Quaternion.Euler(90,0,0);for(int ring=0;ring<3;ring++){var band=SubmarineArt.Model("Pressure tank rolled retaining band",tank.transform,SubmarineArt.Ring(),brass,new Vector3(0,(ring-1)*1.5f,0));band.transform.localScale=Vector3.one*.84f;}var pod=SubmarineArt.Model("Stern ducted thruster bronze rim",root,SubmarineArt.Ring(),metal,new Vector3(side*2.1f,.3f,-3.5f));pod.transform.localRotation=Quaternion.Euler(90,0,0);var prop=SubmarineArt.Model("Swept operational propeller",root,SubmarineArt.Propeller(),brass,new Vector3(side*2.1f,.3f,-3.6f));prop.transform.localScale=Vector3.one*.75f;propellers.Add(prop.transform);var lamp=new GameObject("Ocean expedition forward searchlight").AddComponent<Light>();lamp.transform.SetParent(root,false);lamp.transform.localPosition=new Vector3(side*1.4f,1,3.2f);lamp.type=LightType.Spot;lamp.spotAngle=72;lamp.range=55;lamp.intensity=5;lamp.color=new Color(.7f,.94f,1);lamp.shadows=LightShadows.None;}
