  static ParticleSystem Particles(string name,Transform parent,Vector3 p,bool burst){var system=new GameObject(name).AddComponent<ParticleSystem>();system.transform.SetParent(parent,false);system.transform.localPosition=p;system.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=system.main;main.playOnAwake=false;main.loop=!burst;main.startColor=new Color(.6f,.9f,1,.4f);main.startLifetime=burst?2:1.7f;main.startSize=burst?.3f:.12f;main.startSpeed=burst?18:1.2f;main.maxParticles=192;main.gravityModifier=-.06f;main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=system.emission;emission.rateOverTime=burst?0:6;if(burst)emission.SetBursts(new[]{new ParticleSystem.Burst(0,64)});var shape=system.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=burst?1:.3f;system.GetComponent<ParticleSystemRenderer>().sharedMaterial=Require<Material>("Assets/TruckSheepHerding/Materials/Transparent comic flare.mat");return system;}
