  static void Treasure(SubmarineMatch m,Material metal,Material brass,Material blue,PhysicsMaterial contact){var root=new GameObject("Finite actual native salvage objects").transform;m.treasures=new SubmarineCargo[25];for(int i=0;i<25;i++){float x,z;if(i<5){x=(i-2)*15;z=-90;}else{x=(i%5-2)*42;z=-45+(i/5-1)*52;}var kind=(SubmarineCargoKind)(i%5);var p=new Vector3(x,SubmarineArt.Floor(x,z)+2.4f,z);var holder=new GameObject("Recoverable "+kind+" "+i);holder.layer=2;holder.transform.SetParent(root,false);holder.transform.position=p;var body=holder.AddComponent<Rigidbody>();body.mass=35+i%5*8;body.linearDamping=1;body.angularDamping=1;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.interpolation=RigidbodyInterpolation.Interpolate;var shape=holder.AddComponent<BoxCollider>();shape.size=new Vector3(2.8f,2,2);shape.sharedMaterial=contact;var cargo=holder.AddComponent<SubmarineCargo>();cargo.match=m;cargo.body=body;cargo.shape=shape;cargo.id=i;cargo.kind=kind;cargo.spawn=p;m.treasures[i]=cargo;var material=kind==SubmarineCargoKind.Gold||kind==SubmarineCargoKind.Artifact?brass:kind==SubmarineCargoKind.Cargo?blue:metal;var box=SubmarineArt.Model("Detailed salvage base",holder.transform,SubmarineArt.Box("Rounded salvage chest base",new Vector3(2.6f,1.4f,1.8f)),material,Vector3.zero);for(int side=-1;side<=1;side+=2)SubmarineArt.Model("Salvage retention strap and wear band",holder.transform,SubmarineArt.Box("Salvage chest end strap",new Vector3(.16f,1.6f,1.95f)),brass,new Vector3(side*.85f,0,0));if(kind==SubmarineCargoKind.Chest){var lid=SubmarineArt.Model("Vaulted sunken chest lid",holder.transform,SubmarineArt.Tank(),material,Vector3.up*.7f);lid.transform.localRotation=Quaternion.Euler(0,0,90);lid.transform.localScale=new Vector3(.6f,.5f,.9f);}else if(kind==SubmarineCargoKind.Artifact){var artifact=SubmarineArt.Model("Ancient inscribed ritual amphora",holder.transform,SubmarineArt.Tank(),brass,Vector3.up);artifact.transform.localScale=Vector3.one*.4f;}