  static void OwnedUrp(GameObject instance){foreach(var renderer in instance.GetComponentsInChildren<Renderer>(true)){var list=renderer.sharedMaterials;for(int i=0;i<list.Length;i++){var source=list[i];if(source==null||source.shader.name.Contains("Universal Render Pipeline"))continue;string id=AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(source));var material=Mat("Ocean owned URP "+source.name+" "+id,source.HasProperty("_Color")?source.color:Color.white,.25f);material.mainTexture=source.mainTexture;if(source.HasProperty("_BumpMap")&&source.GetTexture("_BumpMap")!=null){material.SetTexture("_BumpMap",source.GetTexture("_BumpMap"));material.EnableKeyword("_NORMALMAP");}list[i]=material;}renderer.sharedMaterials=list;}}
  static void Wildlife(SubmarineMatch m,Material glow){var root=new GameObject("Licensed animated marine wildlife").transform;root.position=new Vector3(0,-55,0);var controller=root.gameObject.AddComponent<SeaControl>();controller.radius=175;controller.height=68;var animators=new List<Animator>();string[] names={"BlacktipReefShark","MantaRay","SpottedEagleRay","BlueTang","Clownfish","YellowTang"};for(int i=0;i<18;i++){var source=Require<GameObject>(Fish+names[i%names.Length]+".prefab");var fish=(GameObject)PrefabUtility.InstantiatePrefab(source,root);fish.transform.position=new Vector3(Mathf.Cos(i*2.4f)*95,-30-i%5*11,Mathf.Sin(i*2.4f)*125);fish.transform.localScale=Vector3.one*(i%6<3?3:2);var swim=fish.GetComponent<FreeSwimming>();if(swim==null)swim=fish.AddComponent<FreeSwimming>();swim.minSpeed=i%6<3?2:1;swim.maxSpeed=i%6<3?5:3;swim.obstacleLayer=1;foreach(var c in fish.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);var animator=fish.GetComponent<Animator>();if(animator==null)animator=fish.AddComponent<Animator>();animator.runtimeAnimatorController=Require<RuntimeAnimatorController>("Assets/Layer Lab/3D Characters-Fish/Fish/Ani/"+(i%6==0?"shark":i%6<3?"ray":"fish")+".controller");animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;if(!animator.runtimeAnimatorController.animationClips.Any(clip=>AnimationUtility.GetCurveBindings(clip).Any(binding=>binding.type==typeof(Transform)&&animator.transform.Find(binding.path)!=null)))throw new InvalidOperationException("Installed marine clip does not bind this actual authored skeleton: "+source.name);OwnedUrp(fish);animators.Add(animator);}m.presentation.wildlife=animators.ToArray();
   var squid=m.gameObject.AddComponent<SubmarineSquid>();squid.match=m;m.presentation.squid=squid;var model=new GameObject("Rare original articulated giant squid").transform;squid.model=model;var flesh=Mat("Giant squid living rose mantle",new Color(.45f,.1f,.22f),.45f);var mantle=SubmarineArt.Model("Tapered living squid mantle",model,SubmarineArt.SquidMantle(),flesh,Vector3.zero);for(int side=-1;side<=1;side+=2){var eye=SubmarineArt.Model("Giant squid reflective eye",model,SubmarineArt.Ring(),glow,new Vector3(side*2.5f,1,0));eye.transform.localRotation=Quaternion.Euler(0,0,90);}var joints=new List<Transform>();for(int arm=0;arm<8;arm++){var parent=model;for(int segment=0;segment<3;segment++){var joint=new GameObject("Actual squid arm joint "+arm+" section "+segment).transform;joint.SetParent(parent,false);joint.localPosition=segment==0?new Vector3(Mathf.Cos(arm*Mathf.PI/4)*1.8f,-5.5f,Mathf.Sin(arm*Mathf.PI/4)*1.8f):Vector3.up*(6*Mathf.Pow(.7f,segment-1));joint.localRotation=segment==0?Quaternion.Euler(15,arm*45,180):Quaternion.Euler(10,0,0);var mesh=SubmarineArt.Model("Tapering modeled sucker-bearing arm",joint,SubmarineArt.Arm(),flesh,Vector3.zero);mesh.transform.localScale=Vector3.one*Mathf.Pow(.7f,segment);for(int sucker=0;sucker<6;sucker++){var cup=SubmarineArt.Model("Modeled squid suction cup",joint,SubmarineArt.Ring(),glow,new Vector3(0,1+sucker,.45f));cup.transform.localScale=Vector3.one*.12f;cup.transform.localRotation=Quaternion.Euler(90,0,0);}joints.Add(joint);parent=joint;}}squid.armJoints=joints.ToArray();model.gameObject.SetActive(false);
  }
  public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<SubmarineMatch>();if(m==null||m.divers.Length!=4||m.treasures.Length!=25||m.buoy==null||m.drivingViews.rally.trucks.Length!=4)throw new InvalidOperationException("Submarine authoritative scene bindings incomplete.");foreach(var d in m.divers){float expected=(d.truck.GetComponentsInChildren<Rigidbody>(true).Where(body=>body!=d.ballast).Sum(body=>body.mass)+d.truck.body.mass*.08f)/1000;if(d.truck.tractorMotor==null||d.buoyancy==null||d.buoyancy.proxy==null||Mathf.Abs(SubmarineArt.Volume(d.buoyancy.proxy)-expected)>expected*.001f||d.ballastJoint.connectedBody!=d.truck.body||d.gear==null||d.grip==null)throw new InvalidOperationException("Real NWH/Archimeds neutral displacement or welded ballast binding missing.");}if(m.presentation.wildlife.Length!=18||m.presentation.squid.armJoints.Length!=24)throw new InvalidOperationException("Animated marine wildlife incomplete.");Debug.Log("SUBMARINE_SCENE_VALIDATED full NWH4/vendor buoyancy/25 physical salvage/18 animated fish+rare24joint squid");}
